d\\ndesign\\\\feature_descriptions\\\\J_011_narrow_data_service_context.md\\ndesign\\\\feature_descriptions\\\\J_010_split_action_popup.md\\ndesign\\\\feature_descriptions\\\\J_009_split_config_service.md\\ndesign\\\\feature_descriptions\\\\J_008_split_action_runner_helpers.md\\napp\\\\vite.config.ts\\ndesign\\\\feature_descriptions\\\\J_007_split_action_scheduler_service.md\\napp\\\\vite.config.test.ts\\ndesign\\\\feature_descriptions\\\\J_006_split_local_git_service.md\\ndesign\\\\feature_descriptions\\\\J_005_split_data_service_collaborators.md\\ndesign\\\\feature_descriptions\\\\J_004_split_project_toolbar_menu_dialogs.md\\ndesign\\\\feature_descriptions\\\\J_003_refactor_cleanup_dead_files_and_shims.md\\ndesign\\\\feature_descriptions\\\\J_002_refactor_large_modules.md\\ndesign\\\\feature_descriptions\\\\J_001_initialize.md\\ndesign\\\\feature_descriptions\\\\F_72_scrolling_cardview_on_mobile.md\\ndesign\\\\feature_descriptions\\\\F_71_status_bar_mobile.md\\ndesign\\\\feature_descriptions\\\\F_70_layout_add_card.md\\ndesign\\\\feature_descriptions\\\\F_69_config_in_dialog.md\\ndesign\\\\feature_descriptions\\\\F_68_ui_speed_up.md\\ndesign\\\\feature_descriptions\\\\F_67_show_spinner_on_load_project.md\\ndesign\\\\feature_descriptions\\\\F_66_project_in_appbar.md\\ndesign\\\\feature_descriptions\\\\F_65_state_triggers_and_folder_watching.md\\ndesign\\\\feature_descriptions\\\\F_64_agent_actions.md\\ndesign\\\\feature_descriptions\\\\F_63_electron_action_execution_and_chaining.md\\ndesign\\\\feature_descriptions\\\\F_62_action_model_and_loading.md\\ndesign\\\\feature_descriptions\\\\F_62_action_entry_points_and_popup.md\\ndesign\\\\feature_descriptions\\\\F_061_worktree_select_on_action_popup.md\\ndesign\\\\feature_descriptions\\\\F_060_card_commit_diff_viewer.md\\ndesign\\\\feature_descriptions\\\\F_059_mobile_toolbar.md\\ndesign\\\\feature_descriptions\\\\F_058_compact_action_usage_summary.md\\ndesign\\\\feature_descriptions\\\\F_057_edit_prepared_action_prompt