        flushPendingChanges,
        projectFolderProvider: () => projectFolder,
        projectProvider: () => project,
        snapshotProvider: () => projectSnapshot,
        storageProvider: () => storage,
        unassignCardWorktree,
    })

    return { assignCardWorktree, clearCardBranch, unassignCardWorktree }
}

